namespace druta::ui {
bool operator==(const VoltageOffsetKey& a,const VoltageOffsetKey& b){return a.rail==b.rail&&a.role==b.role;}
namespace {
using Bytes=std::vector<uint8_t>;using A=VoltagePolicyAvailability;
struct Error:std::runtime_error{A kind;Error(const std::string& message,A value):std::runtime_error(message),kind(value){}};
[[noreturn]]void fail(const std::string& message,A kind=A::invalid){throw Error(message,kind);}
void require(bool ok,const char* message){if(!ok)fail(message);}
A error_kind(const dc_error& error){return error.kind==DC_ERR_TRANSIENT||error.kind==DC_ERR_UNSTABLE?A::transient:error.kind==DC_ERR_UNSUPPORTED?A::unsupported:A::invalid;}
bool terminated(const char* s,size_t size){return std::memchr(s,0,size)!=nullptr;}
bool target_equal(const dc_target& a,const dc_target& b){return a.size==sizeof(a)&&b.size==sizeof(b)&&terminated(a.slot,sizeof(a.slot))&&terminated(b.slot,sizeof(b.slot))&&a.slot[0]&&a.handle&&a.handle==b.handle&&std::strcmp(a.slot,b.slot)==0&&a.architecture==b.architecture&&a.device_id==b.device_id&&a.subsystem_id==b.subsystem_id;}
uint32_t u32(const Bytes& b,size_t at){require(at<=b.size()&&4<=b.size()-at,"Offset packet field outside bounds");uint32_t value;std::memcpy(&value,b.data()+at,4);return value;}
void put(Bytes& b,size_t at,uint32_t value){require(at<=b.size()&&4<=b.size()-at,"Offset packet projection outside bounds");std::memcpy(b.data()+at,&value,4);}
uint32_t uv_bits(int64_t value){if(value<INT32_MIN||value>INT32_MAX||static_cast<int64_t>(static_cast<float>(value))!=value)fail("Offset requires exact signed int32/float32 microvolts");const auto number=static_cast<float>(value);uint32_t raw;std::memcpy(&raw,&number,4);return raw;}
int64_t uv(const Bytes& b,size_t at){const auto raw=u32(b,at);float value;std::memcpy(&value,&raw,4);if(!std::isfinite(value)||std::trunc(value)!=value||double(value)<INT32_MIN||double(value)>INT32_MAX)fail("Loaded offset is not exact signed microvolts");return static_cast<int64_t>(value);}
size_t policy_field(VbiosVoltageRole role){switch(role){case VbiosVoltageRole::rel:return 0;case VbiosVoltageRole::alt:return 1;case VbiosVoltageRole::ov:return 2;case VbiosVoltageRole::vmin:return 3;default:fail("Unknown installed offset policy");}}
const InstalledVoltageScaffoldHead& head(const VoltageOffsetSnapshot& snapshot,const VoltageOffsetKey& key){const InstalledVoltageScaffoldHead* found=nullptr;for(const auto& value:snapshot.scaffold.heads)if(value.rail==key.rail&&value.role==key.role){if(found)fail("Duplicate installed offset policy");found=&value;}if(!found)fail("Selected offset has no recognized installed head",A::unsupported);return *found;}
void set_value(Bytes& bytes,uint32_t index,int64_t value){const auto raw=uv_bits(value);const size_t at=0x408+0x80*index;for(const auto offset:{4u,8u,16u})put(bytes,at+offset,raw);}
std::string hex(const Bytes& bytes){const char* digits="0123456789abcdef";std::string value;value.reserve(bytes.size()*2);for(auto b:bytes){value+=digits[b>>4];value+=digits[b&15];}return value;}
std::string binding(const VoltageOffsetSnapshot& snapshot,const InstalledVoltageScaffoldHead& h){const size_t at=0x408+0x70*h.index,ct=0x408+0x80*h.index;Bytes info(snapshot.equations.info.begin()+at,snapshot.equations.info.begin()+at+0x70),control(snapshot.equations.control.begin()+ct,snapshot.equations.control.begin()+ct+0x80);for(const auto offset:{4u,8u,16u})put(control,offset,0);
 std::ostringstream out;out<<snapshot.scaffold.receipt_binding<<':'<<snapshot.scaffold.image_sha256<<':'<<h.rail<<':'<<static_cast<unsigned>(h.role)<<':'<<h.index<<':'<<h.next<<':'<<h.variable<<':'<<h.selector_offset<<':'<<h.row_offset<<':'<<hex(info)<<':'<<hex(control);return out.str();}
struct Guard {VoltagePolicyApi& api;dc_gpu* gpu;bool held;Guard(VoltagePolicyApi& a,dc_gpu* g):api(a),gpu(g),held(a.lock&&a.unlock&&a.lock(g)==DC_OK){}~Guard(){if(held)api.unlock(gpu);}};
struct Record {VoltageOffsetRequest request;uint32_t index=0;int64_t before=0;};
}
struct VoltageOffsetsPlan::State {std::shared_ptr<int> session;std::shared_ptr<const VoltageOffsetSnapshot> original;std::vector<VoltageOffsetRequest> requests;};
struct VoltageOffsetsReceipt::State {std::shared_ptr<int> session;std::shared_ptr<const VoltageOffsetSnapshot> original;std::vector<VoltageOffsetRequest> selected;std::vector<Record> records;std::shared_ptr<State> previous;bool complete=false,pending=false;};
struct VoltageOffsetsService::Impl {
 VoltageOffsetsApi api;dc_gpu* gpu;dc_gpu_identity identity;VoltageOffsetsData data;std::function<void()> history;std::shared_ptr<int> session=std::make_shared<int>(0);std::shared_ptr<VoltageOffsetsReceipt::State> undo;
 Impl(VoltageOffsetsApi value,dc_gpu* handle,const dc_gpu_identity& id):api(std::move(value)),gpu(handle),identity(id){data.identity=id;}
 VoltagePolicyApi& transport_api(){return api.transport.transport;}
 dc_target bind(){auto& a=transport_api();if(!a.identity||!a.bind||!a.architecture_supported)fail("Offset target interfaces unavailable",A::unsupported);dc_gpu_identity current{};current.size=sizeof(current);const auto status=a.identity(gpu,&current);if(status!=DC_OK)fail("Offset identity read unavailable",status==DC_E_ARGUMENT?A::invalid:A::transient);
  require(identity.size==sizeof(identity)&&current.size==sizeof(current)&&terminated(identity.slot,sizeof(identity.slot))&&terminated(identity.uuid,sizeof(identity.uuid))&&terminated(identity.pairing_error,sizeof(identity.pairing_error))&&terminated(current.slot,sizeof(current.slot))&&terminated(current.uuid,sizeof(current.uuid))&&terminated(current.pairing_error,sizeof(current.pairing_error)),"Offset adapter identity malformed");
  require(current.nvapi_ok&&current.nvapi_selected&&!current.pairing_error[0]&&!identity.pairing_error[0]&&std::strcmp(current.slot,identity.slot)==0&&std::strcmp(current.uuid,identity.uuid)==0&&current.nvapi_handle==identity.nvapi_handle&&current.nvapi_devid==identity.nvapi_devid&&current.nvapi_subsys==identity.nvapi_subsys&&current.nvml_selected==identity.nvml_selected&&current.nvml_has_devid==identity.nvml_has_devid&&current.nvml_devid==identity.nvml_devid&&current.nvml_subsys==identity.nvml_subsys,"Offset selected adapter changed");
  dc_target target{};target.size=sizeof(target);dc_error error{};error.size=sizeof(error);if(a.bind(gpu,1,&target,&error)!=DC_OK)fail("Offset paired PERF target unavailable",error_kind(error));require(target_equal(target,target)&&std::strcmp(target.slot,current.slot)==0&&target.handle==current.nvapi_handle&&target.device_id==current.nvapi_devid&&target.subsystem_id==current.nvapi_subsys,"Offset PERF target mismatched");if(!a.architecture_supported(target.architecture))fail("Offset architecture unqualified",A::unsupported);return target;
 }
 void qualify(VoltageOffsetSnapshot& snapshot){const auto target=bind();require(target_equal(target,snapshot.scaffold.target)&&target_equal(target,snapshot.equations.target)&&target_equal(target,snapshot.retained.target),"Offset snapshot target differs across independent evidence");
  require(snapshot.equations.info.size()==0xe0408&&snapshot.equations.control.size()==0x100408&&snapshot.equations.info[0]==snapshot.equations.control[0]&&std::equal(snapshot.equations.info.begin()+4,snapshot.equations.info.begin()+0x404,snapshot.equations.control.begin()+4),"Offset native inventory geometry differs");
  require(snapshot.scaffold.receipt_binding.size()==64&&snapshot.scaffold.receipt_binding.find_first_not_of("0123456789abcdef")==std::string::npos&&snapshot.scaffold.image_sha256.size()==64&&snapshot.scaffold.image_sha256.find_first_not_of("0123456789abcdef")==std::string::npos&&snapshot.retained.image_sha256==snapshot.scaffold.image_sha256&&snapshot.retained.retained_requests_qualified&&!snapshot.retained.policy_identity.empty(),"Offset ROM/receipt/retained-request evidence unqualified");
  if(snapshot.retained.boost_percent)require(*snapshot.retained.boost_percent>=0&&*snapshot.retained.boost_percent<=100,"Offset boost percentage malformed");
  for(const auto& rail:snapshot.retained.rails)if(rail.present){for(auto value:rail.policy)require(value>0&&uint64_t(value)<=UINT32_MAX,"Offset independent policy has invalid units");for(auto value:rail.offsets)require(value>=INT32_MIN&&value<=INT32_MAX,"Offset retained rail delta has invalid units");require(rail.boost_uv>=0&&uint64_t(rail.boost_uv)<=UINT32_MAX,"Offset reported boost has invalid units");}
  require(snapshot.scaffold.heads.size()<=8,"Offset head inventory exceeds bounds");std::set<std::pair<uint32_t,VbiosVoltageRole>> keys;std::set<uint32_t> indices;
  for(const auto& h:snapshot.scaffold.heads){require(h.rail<2&&h.index<8192&&h.next<8192&&h.index!=h.next&&h.variable<255&&h.output==2&&keys.insert({h.rail,h.role}).second&&indices.insert(h.index).second,"Offset installed head manifest malformed");(void)policy_field(h.role);const size_t at=0x408+0x70*h.index,ct=0x408+0x80*h.index;
   require((snapshot.equations.info[4+h.index/8]&(1u<<(h.index%8)))&&(snapshot.equations.info[4+h.next/8]&(1u<<(h.next%8)))&&snapshot.equations.info[at]==3&&snapshot.equations.info[at+0x6c]==3&&snapshot.equations.control[ct]==3&&snapshot.equations.control[ct+0x7c]==3&&snapshot.equations.info[at+0x6d]==h.variable&&snapshot.equations.info[at+0x6e]==2&&(u32(snapshot.equations.info,at)&0xffff0000u)==(h.next<<16),"Offset head type/next/variable/output differs from recognition");
   require(uv(snapshot.equations.control,ct+4)==h.value_uv&&uv(snapshot.equations.control,ct+8)==h.value_uv&&uv(snapshot.equations.control,ct+16)==h.value_uv,"Offset head current value differs from recognized request");const auto c1=u32(snapshot.equations.control,ct+20),c2=u32(snapshot.equations.control,ct+24);float a,b;std::memcpy(&a,&c1,4);std::memcpy(&b,&c2,4);require(a==0&&b==0,"Offset head is not an independent constant");}
 }
 void stale(const std::string& message,A kind){for(auto& row:data.rows){row.stale=true;row.writable=false;row.availability=kind;row.message=message;}data.message=message;++data.revision;}
 std::shared_ptr<const VoltageOffsetSnapshot> fresh(){if(!api.capture)fail("Installed offset capture unavailable",A::unsupported);try{auto result=std::make_shared<VoltageOffsetSnapshot>(api.capture(gpu));qualify(*result);return result;}catch(const VoltageEquationEvidenceError& error){stale(error.what(),error.kind);fail(error.what(),error.kind);}catch(const Error& error){stale(error.what(),error.kind);throw;}catch(const std::exception& error){stale(error.what(),A::invalid);fail(error.what());}}
 bool writer_available()const{const auto& a=api.transport.transport;return a.identity&&a.bind&&a.architecture_supported&&a.lock&&a.unlock&&a.transport&&a.escape;}
 std::vector<VoltageOffsetRow> rows(const VoltageOffsetSnapshot& snapshot){std::vector<VoltageOffsetRow> out;for(const auto& h:snapshot.scaffold.heads){VoltageOffsetRow row;row.key={h.rail,h.role};row.value_uv=h.value_uv;row.binding=binding(snapshot,h);const auto& rail=snapshot.retained.rails[h.rail];const bool boost_known=(h.role!=VbiosVoltageRole::rel&&h.role!=VbiosVoltageRole::alt)||snapshot.retained.boost_percent.has_value();row.availability=rail.present?A::available:rail.availability;row.writable=rail.present&&writer_available()&&boost_known&&!(undo&&undo->pending);row.message=rail.present?"Signed installed offset request; not measured voltage":rail.message;if(rail.present&&!writer_available())row.message="Signed offset is inspectable; native writer transport unavailable";else if(rail.present&&!boost_known)row.message="REL/ALT offset is inspectable; independent boost request unavailable";if(rail.present)row.reported_uv=rail.policy[policy_field(h.role)];out.push_back(std::move(row));}return out;}
 void publish(const VoltageOffsetSnapshot& snapshot){auto current=rows(snapshot);for(auto& row:current){const auto old=std::find_if(data.rows.begin(),data.rows.end(),[&](const auto& value){return value.key==row.key;});if(row.availability==A::available)row.initial_uv=old!=data.rows.end()&&old->binding==row.binding?old->initial_uv:row.value_uv;else if(old!=data.rows.end()){const auto availability=row.availability;const auto message=row.message;row=*old;row.stale=true;row.writable=false;row.availability=availability;row.message=message;}}
  for(const auto& old:data.rows)if(std::none_of(current.begin(),current.end(),[&](const auto& row){return row.key==old.key;})){auto retained=old;retained.stale=true;retained.writable=false;retained.availability=A::unsupported;retained.message="Installed head absent from current recognition";current.push_back(std::move(retained));}data.rows=std::move(current);data.target=snapshot.scaffold.target;++data.revision;}
 void flags(){data.undo_available=undo&&!undo->complete;data.recovery_pending=undo&&undo->pending;if(data.recovery_pending)for(auto& row:data.rows)row.writable=false;++data.revision;}
 const InstalledVoltageScaffoldHead& selected(const VoltageOffsetSnapshot& snapshot,const VoltageOffsetRequest& request){const auto& h=head(snapshot,request.key);if(!snapshot.retained.rails[h.rail].present)fail(snapshot.retained.rails[h.rail].message,snapshot.retained.rails[h.rail].availability);require(!request.binding.empty()&&request.binding==binding(snapshot,h),"Offset binding changed since draft");if(request.expected_uv&&*request.expected_uv!=h.value_uv)fail("Offset current request changed since draft");uv_bits(request.value_uv);
  if(!writer_available())fail("Offset singleton writer transport unavailable",A::unsupported);
  if(h.role==VbiosVoltageRole::rel||h.role==VbiosVoltageRole::alt)require(snapshot.retained.boost_percent.has_value(),"REL/ALT offset requires independent boost request");
  const bool derived=snapshot.retained.boost_percent.value_or(0)!=0&&(h.role==VbiosVoltageRole::rel||h.role==VbiosVoltageRole::alt);if(!(derived&&h.role==VbiosVoltageRole::rel)){const auto wanted=snapshot.retained.rails[h.rail].policy[policy_field(h.role)]+request.value_uv-h.value_uv;require(wanted>0&&uint64_t(wanted)<=UINT32_MAX,"Offset would produce an invalid independently reported policy");}return h;
 }
 void policy(const VoltageOffsetSnapshot& before,const VoltageOffsetSnapshot& after,const Record& record,int64_t prior,int64_t wanted){const auto& a=before.retained;const auto& b=after.retained;
  require(target_equal(before.scaffold.target,after.scaffold.target)&&before.scaffold.receipt_binding==after.scaffold.receipt_binding&&before.scaffold.image_sha256==after.scaffold.image_sha256&&a.policy_identity==b.policy_identity&&a.rail_requests==b.rail_requests&&a.clock_requests==b.clock_requests&&a.boost_percent==b.boost_percent&&b.retained_requests_qualified,"Offset changed retained requests, image or independent policy identity");
  const bool derived=a.boost_percent.value_or(0)!=0&&(record.request.key.role==VbiosVoltageRole::rel||record.request.key.role==VbiosVoltageRole::alt);
  for(size_t rail=0;rail<2;++rail){require(a.rails[rail].present==b.rails[rail].present&&a.rails[rail].offsets==b.rails[rail].offsets,"Offset changed rail availability or retained offsets");if(!a.rails[rail].present)continue;
   if(!derived)require(a.rails[rail].boost_uv==b.rails[rail].boost_uv,"Offset changed unrelated reported boost");
   for(size_t field=0;field<5;++field){if((field==4&&rail==record.request.key.rail)||(derived&&(field==0||field==4)))continue;const auto expected=a.rails[rail].policy[field]+(rail==record.request.key.rail&&field==policy_field(record.request.key.role)?wanted-prior:0);require(b.rails[rail].policy[field]==expected,"Reported selected offset delta or unrelated policy differs");}
  }
 }
 void packet_preservation(const VoltageOffsetSnapshot& before,const VoltageOffsetSnapshot& after,uint32_t index,int64_t value){auto expected=before.equations.control;set_value(expected,index,value);require(before.equations.info==after.equations.info&&expected==after.equations.control,"Offset readback changed unknown/unselected equation bytes or selected request");}
 dc_rm_transport envelope(){auto& a=transport_api();if(!a.transport||!a.escape)fail("Offset singleton writer transport unavailable",A::unsupported);const auto target=bind();dc_rm_transport t{};t.size=sizeof(t);dc_error error{};error.size=sizeof(error);if(a.transport(gpu,&t,&error)!=DC_OK)fail("Offset transport capture failed",error_kind(error));require(t.size==sizeof(t)&&t.captured==1&&t.header_count==17&&t.header[0]==0x4e564441&&t.header[1]==0x10002&&t.header[3]==0x4e562a2a&&t.header[4]==0x0500002b&&uint64_t(t.header[2])==68+uint64_t(t.header[15]),"Offset transport envelope unqualified");require(target_equal(target,bind()),"Offset target changed around transport read");return t;}
 bool send(const VoltageOffsetSnapshot& current,uint32_t index,int64_t value,const std::function<void()>& journal,bool& dispatched){const auto t=envelope();constexpr size_t size=0x100408,total=68+size;std::vector<uint32_t> buffer(total/4+32,0xa5a5a5a5);auto* words=buffer.data()+16;std::copy(t.header,t.header+17,words);words[2]=uint32_t(total);words[5]=words[11]=words[16]=0;words[14]=0x2080e0b7;words[15]=uint32_t(size);auto* bytes=reinterpret_cast<uint8_t*>(words+17);auto projected=current.equations.control;set_value(projected,index,value);std::fill_n(projected.begin()+4,1024,uint8_t{0});projected[4+index/8]=uint8_t(1u<<(index%8));std::copy(projected.begin(),projected.end(),bytes);std::array<uint32_t,16> expected;std::copy_n(words,16,expected.begin());require(target_equal(current.scaffold.target,bind()),"Offset target changed before SET");
  journal();dc_error error{};error.size=sizeof(error);int32_t nt=0;dispatched=true;const auto status=transport_api().escape(gpu,reinterpret_cast<uint8_t*>(words),total,&t.fields,&nt,&error);
  if(!std::all_of(buffer.begin(),buffer.begin()+16,[](auto v){return v==0xa5a5a5a5;})||!std::all_of(buffer.end()-16,buffer.end(),[](auto v){return v==0xa5a5a5a5;}))fail("Offset SET exceeded packet bounds");require(target_equal(current.scaffold.target,bind()),"Offset target changed during SET");
  for(size_t i=0;i<16;++i)if(i!=5&&i!=11)require(words[i]==expected[i],"Offset SET changed routing/geometry");require(words[5]<=1,"Offset SET context output malformed");
  if(status==DC_E_UNAVAILABLE){dispatched=false;return false;}if(status!=DC_OK)fail("Offset SET transport failed",error_kind(error));if(nt)fail("Offset SET NTSTATUS failed",A::transient);if(words[11]!=1)fail("Offset SET response incomplete",A::transient);if(words[16])fail("Offset SET RM rejected",words[16]==0x1f||words[16]==0x56?A::unsupported:A::transient);require(std::equal(projected.begin(),projected.end(),bytes),"Offset SET modified caller-owned request");return true;
 }
 void compare_selected(const VoltageOffsetSnapshot& current,const VoltageOffsetsPlan::State& plan,bool desired){require(target_equal(current.scaffold.target,plan.original->scaffold.target),"Offset plan target changed");for(const auto& request:plan.requests){const auto& h=head(current,request.key);require(binding(current,h)==request.binding&&h.value_uv==(desired?request.value_uv:head(*plan.original,request.key).value_uv),"Whole selected offset request/binding changed");}}
 void receipt_candidates(const VoltageOffsetSnapshot& current,const VoltageOffsetsReceipt::State& receipt){require(receipt.session==session&&receipt.original&&target_equal(current.scaffold.target,receipt.original->scaffold.target),"Offset receipt belongs to another session or adapter");auto normalized=current.equations.control;
  require(current.scaffold.receipt_binding==receipt.original->scaffold.receipt_binding&&current.scaffold.image_sha256==receipt.original->scaffold.image_sha256&&current.retained.policy_identity==receipt.original->retained.policy_identity&&current.retained.rail_requests==receipt.original->retained.rail_requests&&current.retained.clock_requests==receipt.original->retained.clock_requests&&current.retained.boost_percent==receipt.original->retained.boost_percent,"Offset recovery retained request or receipt binding changed");
  for(const auto& record:receipt.records){const auto& h=head(current,record.request.key);require(binding(current,h)==record.request.binding&&(h.value_uv==record.before||h.value_uv==record.request.value_uv),"Offset recovery conflicts with current selected request");set_value(normalized,record.index,record.before);}
  require(current.equations.info==receipt.original->equations.info&&normalized==receipt.original->equations.control,"Offset recovery has foreign unknown/unselected equation changes");
 }
};
VoltageOffsetsService::VoltageOffsetsService(VoltageOffsetsApi api,dc_gpu* gpu,const dc_gpu_identity& identity):impl_(std::make_unique<Impl>(std::move(api),gpu,identity)){}
VoltageOffsetsService::~VoltageOffsetsService()=default;
const VoltageOffsetsData& VoltageOffsetsService::state()const{return impl_->data;}
const VoltageOffsetsData& VoltageOffsetsService::read(){auto& p=*impl_;Guard guard(p.transport_api(),p.gpu);if(!guard.held){p.stale("Offset read lock unavailable",A::transient);return p.data;}try{p.publish(*p.fresh());p.data.message="Installed signed offset requests captured";}catch(const std::exception& error){p.data.message=error.what();}p.flags();return p.data;}
VoltageOffsetsPlan VoltageOffsetsService::preview(const std::vector<VoltageOffsetRequest>& requests){auto& p=*impl_;VoltageOffsetsPlan result;Guard guard(p.transport_api(),p.gpu);if(!guard.held){result.message="Offset preview lock unavailable";return result;}
 try{require(!(p.undo&&p.undo->pending),"Resolve uncertain offset requests before another plan");require(!requests.empty()&&requests.size()<=8,"Select installed offset policies");const auto current=p.fresh();std::set<std::pair<uint32_t,VbiosVoltageRole>> keys;std::set<uint32_t> indices;
  for(const auto& request:requests){require(request.key.rail<2&&keys.insert({request.key.rail,request.key.role}).second,"Duplicate or invalid offset policy");const auto& h=p.selected(*current,request);require(indices.insert(h.index).second,"Selected offset policies alias one native equation");}
  auto state=std::make_shared<VoltageOffsetsPlan::State>();state->session=p.session;state->original=current;state->requests=requests;result.state=std::move(state);result.ok=true;result.message="All selected signed offset requests preflighted; Apply remains explicit";p.publish(*current);
 }catch(const std::exception& error){result.message=error.what();}p.flags();return result;
}
VoltageOffsetsResult VoltageOffsetsService::apply(const std::vector<VoltageOffsetRequest>& requests){const auto plan=preview(requests);if(!plan.ok)return {false,false,false,plan.message};bool captured=false;return apply_profile(plan,[&](const VoltageOffsetsReceipt&){if(!captured&&impl_->history){impl_->history();captured=true;}});}
void VoltageOffsetsService::set_history_callback(std::function<void()> callback){impl_->history=std::move(callback);}
VoltageOffsetsResult VoltageOffsetsService::apply_profile(const VoltageOffsetsPlan& plan,const std::function<void(const VoltageOffsetsReceipt&)>& journal){auto& p=*impl_;VoltageOffsetsResult result;Guard guard(p.transport_api(),p.gpu);if(!guard.held){result.message="Offset Apply lock unavailable";return result;}
 std::shared_ptr<VoltageOffsetsReceipt::State> receipt;bool dispatched=false,appended=false;
 try{require(plan.ok&&plan.state&&plan.state->session==p.session&&plan.state->original,"Offset plan belongs to another session");require(!(p.undo&&p.undo->pending),"Resolve uncertain offset requests first");const auto current=p.fresh();p.compare_selected(*current,*plan.state,false);for(const auto& request:plan.state->requests)p.selected(*current,request);
  receipt=std::make_shared<VoltageOffsetsReceipt::State>();receipt->session=p.session;receipt->original=current;receipt->selected=plan.state->requests;receipt->previous=p.undo;
  for(const auto& request:plan.state->requests){const auto before=p.fresh();p.receipt_candidates(*before,*receipt);const auto& selected=p.selected(*before,request);require(selected.value_uv==head(*plan.state->original,request.key).value_uv,"Selected offset changed after whole preflight");if(selected.value_uv==request.value_uv)continue;
   Record record{request,selected.index,selected.value_uv};dispatched=false;appended=false;
   const auto before_effect=[&]{receipt->records.push_back(record);appended=true;if(journal)journal(VoltageOffsetsReceipt{receipt});p.undo=receipt;};
   if(!p.send(*before,selected.index,request.value_uv,before_effect,dispatched)){if(appended)receipt->records.pop_back();appended=false;if(receipt->records.empty())p.undo=receipt->previous;fail("Offset SET was not dispatched",A::unsupported);}
   const auto after=p.fresh();p.packet_preservation(*before,*after,selected.index,request.value_uv);p.policy(*before,*after,record,record.before,request.value_uv);p.publish(*after);appended=false;
  }
  const auto after=p.fresh();p.receipt_candidates(*after,*receipt);p.compare_selected(*after,*plan.state,true);p.publish(*after);result.ok=true;result.message=receipt->records.empty()?"All selected offset requests already matched; previous Undo retained":"Selected signed offsets applied and verified";
 }catch(const std::exception& error){if(receipt){if(appended&&!dispatched){receipt->records.pop_back();if(receipt->records.empty())p.undo=receipt->previous;}if(!receipt->records.empty()){receipt->pending=true;p.undo=receipt;}result.may_have_changed=!receipt->records.empty();}result.message=error.what();}
 if(receipt&&!receipt->records.empty())result.may_have_changed=true;p.data.message=result.message;p.flags();return result;
}
VoltageOffsetsResult VoltageOffsetsService::verify(const VoltageOffsetsPlan& plan){auto& p=*impl_;VoltageOffsetsResult result;Guard guard(p.transport_api(),p.gpu);if(!guard.held){result.message="Offset verify lock unavailable";return result;}try{require(plan.ok&&plan.state&&plan.state->session==p.session&&plan.state->original,"Offset plan belongs to another session");p.compare_selected(*p.fresh(),*plan.state,true);result.ok=true;result.message="Entire selected offset plan verified";}catch(const std::exception& error){result.message=error.what();}return result;}
VoltageOffsetsResult VoltageOffsetsService::verify(const VoltageOffsetsReceipt& receipt,bool original){auto& p=*impl_;VoltageOffsetsResult result;Guard guard(p.transport_api(),p.gpu);if(!guard.held){result.message="Offset receipt verify lock unavailable";return result;}try{require(receipt.state&&receipt.state->session==p.session&&receipt.state->original,"Offset receipt belongs to another session");const auto current=p.fresh();p.receipt_candidates(*current,*receipt.state);for(const auto& record:receipt.state->records)require(head(*current,record.request.key).value_uv==(original?record.before:record.request.value_uv),"Issued offset receipt value differs");result.ok=true;result.message=original?"Original issued offset requests verified":"Issued signed offset requests verified";}catch(const std::exception& error){result.message=error.what();}return result;}
VoltageOffsetsResult VoltageOffsetsService::restore(const VoltageOffsetsReceipt& receipt){auto& p=*impl_;VoltageOffsetsResult result;Guard guard(p.transport_api(),p.gpu);if(!guard.held){result.message="Offset restore lock unavailable";return result;}bool started=false;
 try{require(receipt.state&&receipt.state->session==p.session&&receipt.state->original&&!receipt.state->records.empty(),"Offset restore receipt invalid or belongs to another session");auto current=p.fresh();p.receipt_candidates(*current,*receipt.state);
  for(auto it=receipt.state->records.rbegin();it!=receipt.state->records.rend();++it){current=p.fresh();p.receipt_candidates(*current,*receipt.state);const auto& h=head(*current,it->request.key);if(h.value_uv==it->before)continue;bool dispatched=false;
   const auto mark=[&]{started=true;};try{if(!p.send(*current,it->index,it->before,mark,dispatched))fail("Offset restoration was not dispatched",A::unsupported);}catch(...){result.may_have_changed|=dispatched;throw;}result.may_have_changed|=dispatched;
   const auto after=p.fresh();p.packet_preservation(*current,*after,it->index,it->before);p.policy(*current,*after,*it,h.value_uv,it->before);p.publish(*after);
  }
  current=p.fresh();p.receipt_candidates(*current,*receipt.state);for(const auto& record:receipt.state->records)require(head(*current,record.request.key).value_uv==record.before,"Final original offset readback differs");
  receipt.state->complete=true;receipt.state->pending=false;if(p.undo==receipt.state)p.undo=receipt.state->previous;p.publish(*current);result.ok=result.rollback_verified=true;result.message="Original issued offsets restored and verified";
 }catch(const std::exception& error){if(started&&receipt.state){receipt.state->pending=true;p.undo=receipt.state;}result.message=error.what();}p.data.message=result.message;p.flags();return result;
}
VoltageOffsetsResult VoltageOffsetsService::undo(){if(!impl_->undo)return {false,false,false,"No offset Undo retained"};return restore(VoltageOffsetsReceipt{impl_->undo});}
VoltageOffsetsResult VoltageOffsetsService::recover(){return undo();}
VoltageOffsetsResult VoltageOffsetsService::restore_initial(const VoltageOffsetKey& key){const auto& current=read();const auto found=std::find_if(current.rows.begin(),current.rows.end(),[&](const auto& row){return row.key==key;});if(found==current.rows.end()||!found->initial_uv||!found->value_uv||!found->writable||found->stale)return {false,false,false,"Qualified captured initial offset unavailable"};return apply(VoltageOffsetRequest{key,*found->initial_uv,found->binding,found->value_uv});}
}
